class HealthCheck:
    def __init__(self):
        self.checks = {}

    def register(self, name, check_func):
        """Register a health check function"""
        self.checks[name] = check_func

    def run_checks(self):
        """Execute all registered health checks"""
        results = {}
        for name, check in self.checks.items():
            try:
                results[name] = check()
            except Exception as e:
                results[name] = {
                    'status': 'error',
                    'message': str(e)
                }
        return results

